1	// Shared test helpers: spawn server.mjs as a child process and talk HTTP to it.
2	import { spawn } from 'node:child_process';
3	import http from 'node:http';
4	import { mkdtemp, rm } from 'node:fs/promises';
5	import os from 'node:os';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	
9	export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
10	export const SERVER = path.join(ROOT, 'server.mjs');
11	export const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
12	const START_TIMEOUT_MS = 5000;
13	
14	export async function makeTempDir() {
15	  return mkdtemp(path.join(os.tmpdir(), 'bookings-test-'));
16	}
17	
18	export async function removeDir(dir) {
19	  await rm(dir, { recursive: true, force: true });
20	}
21	
22	// Builds the child env: inherited env without PORT/DATA_FILE, then `env`
23	// (a value of undefined leaves the variable unset).
24	function childEnv(env) {
25	  const merged = { ...process.env };
26	  delete merged.PORT;
27	  delete merged.DATA_FILE;
28	  for (const [key, value] of Object.entries(env)) {
29	    if (value !== undefined) merged[key] = value;
30	  }
31	  return merged;
32	}
33	
34	function spawnServer({ env = {}, cwd = ROOT } = {}) {
35	  const child = spawn(process.execPath, [SERVER], {
36	    cwd,
37	    env: childEnv(env),
38	    stdio: ['ignore', 'pipe', 'pipe'],
39	  });
40	  const out = { stdout: '', stderr: '' };
41	  child.stdout.setEncoding('utf8');
42	  child.stderr.setEncoding('utf8');
43	  child.stdout.on('data', (d) => { out.stdout += d; });
44	  child.stderr.on('data', (d) => { out.stderr += d; });
45	  const exited = new Promise((resolve) => {
46	    child.on('exit', (code, signal) => resolve({ code, signal }));
47	  });
48	  return { child, out, exited };
49	}
50	
51	// Runs the server and expects it to exit by itself; returns { code, stdout, stderr }.
52	export async function runUntilExit(options) {
53	  const { child, out, exited } = spawnServer(options);
54	  const timer = setTimeout(() => child.kill('SIGKILL'), START_TIMEOUT_MS);
55	  const { code, signal } = await exited;
56	  clearTimeout(timer);
57	  return { code, signal, stdout: out.stdout, stderr: out.stderr };
58	}
59	
60	// Starts the server (PORT=0 unless given) and waits for the listening line.
61	// Returns { port, child, out, stop }; stop() kills it and waits for exit.
62	export async function startServer({ env = {}, cwd } = {}) {
63	  const fullEnv = { PORT: '0', ...env };
64	  const { child, out, exited } = spawnServer({ env: fullEnv, cwd });
65	  const port = await new Promise((resolve, reject) => {
66	    const timer = setTimeout(() => reject(new Error(`no listening line; stderr: ${out.stderr}`)), START_TIMEOUT_MS);
67	    const onData = () => {
68	      if (!out.stdout.includes('\n')) return;
69	      clearTimeout(timer);
70	      child.stdout.off('data', onData);
71	      const match = LISTEN_RE.exec(out.stdout);
72	      if (match) resolve(Number(match[1]));
73	      else reject(new Error(`unexpected stdout: ${JSON.stringify(out.stdout)}`));
74	    };
75	    child.stdout.on('data', onData);
76	    exited.then(({ code }) => {
77	      clearTimeout(timer);
78	      reject(new Error(`server exited with ${code}; stderr: ${out.stderr}`));
79	    });
80	  });
81	  const stop = async () => {
82	    if (child.exitCode === null && child.signalCode === null) child.kill('SIGTERM');
83	    await exited;
84	  };
85	  return { port, child, out, exited, stop };
86	}
87	
88	// Sends one raw HTTP request; the path is sent byte for byte as given.
89	// Returns { status, headers, raw (Buffer), text, json (or undefined) }.
90	export function request(port, { method = 'GET', path: target = '/', headers = {}, body } = {}) {
91	  return new Promise((resolve, reject) => {
92	    const req = http.request({
93	      host: '127.0.0.1', port, method, path: target, headers, agent: false,
94	    }, (res) => {
95	      const chunks = [];
96	      res.on('data', (c) => chunks.push(c));
97	      res.on('end', () => {
98	        const raw = Buffer.concat(chunks);
99	        const text = raw.toString('utf8');
100	        let json;
101	        try { json = JSON.parse(text); } catch { json = undefined; }
102	        resolve({ status: res.statusCode, headers: res.headers, raw, text, json });
103	      });
104	      res.on('error', reject);
105	    });
106	    req.on('error', reject);
107	    if (body !== undefined) req.write(body);
108	    req.end();
109	  });
110	}
111	
112	export const JSON_CT = 'application/json; charset=utf-8';
113	
114	export function postJson(port, value, headers = { 'Content-Type': 'application/json' }) {
115	  const body = typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value);
116	  return request(port, { method: 'POST', path: '/api/bookings', headers, body });
117	}
118	
119	export function booking(overrides = {}) {
120	  return {
121	    room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00', ...overrides,
122	  };
123	}
